import { useCurrentFrame } from "remotion";
import { Chip, Entrada, Texto, Titulo } from "../componentes/Caixa";
import { IconeFiscal } from "../componentes/Icones";
import { Lei } from "../componentes/Lei";
import { BarraUrl } from "../componentes/Navegador";
import { Area, Etiqueta, Surge } from "../componentes/Quadro";
import { rampa, suave } from "../componentes/util";
import { useFormato } from "../formato";
import { COR, FONTE, MONO } from "../tema";
import type { CenaProps } from "./registro";

/** Dois fiscais, um de cada lado, com setas que se cruzam: a conferência cruzada. */
const Cruzada: React.FC<{ q: number; qRotulo: number; qConfianca: number }> = ({ q, qRotulo, qConfianca }) => {
  const frame = useCurrentFrame();
  const { vertical, t } = useFormato();
  // No 9:16 o lugar fica reservado desde o começo, para os blocos não pularem na coluna.
  const Aparece = vertical ? Surge : Entrada;
  const traco = suave(rampa(frame, q + 6, q + 36));
  const largura = t(vertical ? 1000 : 620);
  const altura = t(vertical ? 200 : 170);
  const lado = t(vertical ? 104 : 84);
  const fiscal = (cor: string, rotulo: string) => (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: t(6), width: t(vertical ? 220 : 190) }}>
      <div style={{ width: lado, height: lado, borderRadius: "50%", border: `3px solid ${cor}`, background: COR.fundo1, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <IconeFiscal tamanho={lado * 0.62} cor={cor} />
      </div>
      <span style={{ fontFamily: MONO, fontSize: t(vertical ? 24 : 16), color: cor, letterSpacing: 1, textAlign: "center" }}>{rotulo}</span>
    </div>
  );
  return (
    <Aparece inicio={q} de="baixo">
      <div style={{ position: "relative", width: largura, height: altura, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        {fiscal(COR.flavio, "fiscal de um lado")}
        <svg width={largura - t(vertical ? 440 : 380)} height={altura} viewBox="0 0 100 60" preserveAspectRatio="none" style={{ position: "absolute", left: t(vertical ? 220 : 190), top: 0 }}>
          <path d="M2 18 C 40 18, 60 42, 98 42" fill="none" stroke={COR.flavio} strokeWidth={1.6} pathLength={1} strokeDasharray={1} strokeDashoffset={1 - traco} />
          <path d="M98 18 C 60 18, 40 42, 2 42" fill="none" stroke={COR.lula} strokeWidth={1.6} pathLength={1} strokeDasharray={1} strokeDashoffset={1 - traco} />
        </svg>
        {fiscal(COR.lula, "fiscal do outro lado")}
        <div style={{ position: "absolute", left: 0, right: 0, top: altura / 2 - t(22), display: "flex", justifyContent: "center" }}>
          <Entrada inicio={qRotulo} de="zoom">
            <Chip cor={COR.outros} solido tamanho={vertical ? 22 : 17}>
              conferência cruzada
            </Chip>
          </Entrada>
        </div>
      </div>
      <Aparece inicio={qConfianca} de="baixo">
        <div style={{ fontFamily: FONTE, fontWeight: 700, fontSize: t(vertical ? 50 : 36), color: COR.tinta, textAlign: "center", width: largura }}>
          = confiança no resultado
        </div>
      </Aparece>
    </Aparece>
  );
};

/**
 * Camada 1: fiscal de partido. Cartão de lei com o que a Lei 9.504 e a Resolução 23.751 garantem,
 * a conferência cruzada e o site de cadastro do PL, com o prazo que o próprio site informa.
 */
export const DepoisFiscais: React.FC<CenaProps> = ({ g }) => {
  const { vertical, t } = useFormato();
  // No 9:16 cada bloco tem o lugar reservado desde o começo e a coluna se espalha pela altura.
  const Aparece = vertical ? Surge : Entrada;
  const lei = (
    <Lei
      titulo="O QUE A LEI GARANTE"
      inicio={g.lei}
      tamanho={vertical ? 36 : 27}
      reservar={vertical}
      itens={[
        { texto: "Fiscalizar todas as fases da votação e da apuração", referencia: "Lei 9.504/1997, art. 66", q: g.fiscalizar },
        { texto: "Até 2 fiscais por seção, 1 por vez", referencia: "Lei 9.504, art. 65, § 4º · Res. TSE 23.751/2026, art. 175, § 1º", q: g.dois },
        { texto: "Credencial expedida pelo próprio partido", referencia: "Lei 9.504, art. 65, § 2º · Res. 23.751, art. 175, § 8º", q: g.credenciados },
        { texto: "Cópia do boletim a quem pedir no encerramento", referencia: "Lei 9.504, art. 68, § 1º · Res. 23.751, art. 127, XV", q: g.copia },
      ]}
      rodape="Lei 9.504/1997, arts. 65, 66 e 68 · Res. TSE 23.751/2026, arts. 175 a 177 (crachá só com nome e partido)"
    />
  );
  const cadastro = (
    <div style={{ display: "flex", flexDirection: "column", gap: t(14) }}>
      <Aparece inicio={g.site - 6} de="esquerda">
        <Texto tamanho={vertical ? 34 : 26} cor={COR.suave}>
          Quem quiser ser fiscal do PL começa em
        </Texto>
      </Aparece>
      <BarraUrl url="fiscaisdopl.com.br" inicio={g.site} cor={COR.ouro} tamanho={vertical ? 54 : 42} />
      <div style={{ display: "flex", gap: t(12), flexWrap: "wrap" }}>
        <Aparece inicio={g.prazo} de="baixo">
          <Etiqueta cor={COR.ouro} solido tamanho={vertical ? 30 : 24}>
            cadastro até 24/10
          </Etiqueta>
        </Aparece>
        <Aparece inicio={g.prazo + 8} de="baixo">
          <Etiqueta cor={COR.suave} tamanho={vertical ? 22 : 18}>
            prazo do próprio site, não da Justiça Eleitoral
          </Etiqueta>
        </Aparece>
      </div>
    </div>
  );
  return (
    <Area style={{ gap: t(vertical ? 36 : 24), justifyContent: vertical ? "space-between" : "flex-start", paddingBottom: vertical ? t(20) : 0 }}>
      <Entrada inicio={0} de="esquerda">
        <div style={{ display: "flex", alignItems: "center", gap: t(18), flexWrap: "wrap" }}>
          <Chip cor={COR.outros} solido tamanho={vertical ? 24 : 22}>
            camada 1 de 3
          </Chip>
          <Titulo tamanho={vertical ? 64 : 56}>Fiscal de partido, de todos os lados</Titulo>
        </div>
      </Entrada>
      <div style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: vertical ? "column" : "row", gap: t(40), justifyContent: vertical ? "space-between" : undefined }}>
        <div style={{ flex: vertical ? "none" : "1.15 1 0", minWidth: 0 }}>{lei}</div>
        <div style={{ flex: vertical ? "none" : "1 1 0", minWidth: 0, display: "flex", flexDirection: "column", gap: t(vertical ? 56 : 34), justifyContent: "flex-start" }}>
          <Cruzada q={g.confere} qRotulo={g.cruzada} qConfianca={g.confianca} />
          {cadastro}
        </div>
      </div>
    </Area>
  );
};

